TESTDATA["pet6-t4"] = {"title": "Cambridge PET 6 · Test 4", "format": "2010", "reading": [{"part": 1, "items": [{"n": 1, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["The members of the gym think the music system is very useful.", "When using the music system in the gym, please remember to switch it off.", "If you put on some music, consider the other people in the gym."], "answer": "C"}, {"n": 2, "text": "", "img": "data:image/jpeg;base64,", "q": "The writer is", "options": ["going home with the rest of the group tomorrow.", "going on a boat with members of the group tomorrow.", "going out with the whole group tomorrow."], "answer": "B"}, {"n": 3, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["You should return your books to the assistant in the correct order.", "The books are easy to find because they are all arranged by level.", "You should replace books in the order that you found them."], "answer": "C"}, {"n": 4, "text": "", "img": "data:image/jpeg;base64,", "q": "", "options": ["Use this button to call hotel staff if you cannot get in.", "If you cannot lock the door, please contact hotel reception.", "Press this button to unlock the entrance door."], "answer": "A"}, {"n": 5, "text": "", "img": "data:image/jpeg;base64,", "q": "What should David do?", "options": ["He should remind Carla that someone is picking her up for band practice.", "He should check Carla is dressed properly and take her to band practice.", "He should make Carla practise before she goes to her school band meeting."], "answer": "B"}]}, {"part": 2, "people": [{"n": 6, "name": "Mary and George", "text": "Mary and George, a retired couple, want to go on a short walk that lasts about an hour. They like old houses and pretty countryside, but can’t climb steep hills.", "answer": "E"}, {"n": 7, "name": "The Thompson family", "text": "The Thompson family want to spend a day out, including lunch. The parents like visiting gardens, but aren’t interested in country houses. The two children are very active and like animals.", "answer": "C"}, {"n": 8, "name": "Carolina and Juan", "text": "Carolina and Juan are experienced, independent walkers. They would like a long walk followed by a meal in a pub. Although they like attractive old villages, they don’t enjoy crowded places.", "answer": "F"}, {"n": 9, "name": "Kenzo", "text": "Kenzo would like to join an organised walk to learn about the area. He is interested in history and wants to see one of the best-known places in this part of the country.", "answer": "H"}, {"n": 10, "name": "Belinda and Tom", "text": "Belinda and her young teenage son Tom both enjoy being outdoors. Belinda wants to go walking and then find a nice café to relax in. Tom gets bored just walking and prefers other activities, especially sports.", "answer": "B"}], "texts": [{"letter": "A", "title": "Lime House and Country Park", "text": "The house attracts thousands of visitors, but this is a pleasant walk for the fit! away from the crowds, through parkland, woods and up onto the hills. Popular with bird-watchers. Allow three hours. The house was built in 1570. Gardens closed to the public; information centre, café and souvenir shop open daily."}, {"letter": "B", "title": "Howden Lake", "text": "This two-hour walk attracts thousands of visitors. When the water is low, you can see a village which was flooded 300 years ago. Quiet café with beautiful views. Children can go sailing and windsurfing on the lake with trained instructors."}, {"letter": "C", "title": "Devonshire Park", "text": "Take a really enjoyable walk in the countryside surrounding the park. Allow at least half a day, or make it a full day by visiting the adventure playground and farmyard (both great for young children). Stop at the café (open all day) or enjoy the fantastic gardens, with beautiful fountains. Guided walks available for small groups."}, {"letter": "D", "title": "Stanton", "text": "This walk is definitely for very fit walkers only – the tracks get very slippery after rain. Allow six hours and start early! You’re unlikely to meet another person all day. Fantastic views of farmland in the valleys below. Be sure to pack sandwiches – you’ll be up on the hilltops all day."}, {"letter": "E", "title": "How Hill", "text": "A leisurely way to spend an hour or two is by visiting the busy village of Hope with its lovely old cottages, traditional pubs and country gardens. A gentle walk towards the hills will soon bring you to superb views."}, {"letter": "F", "title": "Stiper", "text": "You need to be used to walking to successfully complete this seven-hour walk through the wildest scenery in the area. Follow a little-known footpath to the highest point for miles. The traditional pub down in the village serves hot food from 12.00 daily."}, {"letter": "G", "title": "Conford", "text": "This is an easy walk through a little-known valley beside clear streams with woodland flowers, birds and animals. See the 200-year-old buildings from the cloth-making industry which now stand empty. Private tours can be arranged. Allow half a day for the walk."}, {"letter": "H", "title": "Langsett", "text": "After a steep climb, this is an exciting walk along easy paths, which are crowded at weekends (people come from all over Britain to climb Langsett). The views are dramatic, and it’s a popular place for family picnics. Guided walks start from the nearby village (10 am Sundays) and visit 800-year-old woodland and ruins dating back two thousand years."}]}, {"part": 3, "title": "", "text": "You could win £1,000 in this year’s Fiction Prize and have your story printed in Keep Writing magazine. Ten other lucky people will win a cheque for £100.\n\nOnce again, we need people who can write good stories. The judges, who include Mary Littlejohn, the novelist, Michael Brown, the television reporter, and Susan Hitchins, Keep Writing’s editor, are looking for interesting and original stories. Detective fiction was extremely popular last year, although the competition winner produced a love story. You can write about whatever you want but here’s some advice to start you thinking: * Write about what you know This is the advice which every writer should pay attention to and, last year, nearly everyone who wrote for us did exactly that. Love, family, problems with friends - these were the main subjects of the stories. However, you need to turn ordinary situations into something interesting that people will want to read about. Make the reader want to continue reading by writing about ordinary things in a new and surprising way.\n• Get your facts right It’s no good giving a description of a town or explaining how a jet engine works if you get it wrong. So avoid writing anything unless you're certain about it.\n• Hold the reader’s attention Make the beginning interesting and the ending a surprise. There is nothing worse than a poor ending. Develop the story carefully and try to think of something unusual happening at the end. * Think about the characters Try to bring the people in your story alive for the reader by using well-chosen words to make them seem real.\n\nYour story must be your own work, between 2,000 and 2,500 words and typed, double-spaced, on one side only of each sheet of paper.\n\nEven if you're in danger of missing the closing date, we are unable to accept stories by fax or email. You must include the application form with your story. Unfortunately your story cannot be returned, nor can we discuss our decisions.\n\nYou should not have had any fiction printed in any magazine or book in this country — a change in the rules by popular request — and the story must not have appeared in print or in recorded form, for example on radio or TV, anywhere in the world.\n\nYour fee of £5 will go to the Writers’ Association. Make your cheque payable to Keep Writing and send it with the application form and your story to: Keep Writing 75 Broad Street Birmingham B12 4TG The closing date is 30 July and we will inform the winner within one month of this date. Please note that if you win, you must agree to have your story printed in our magazine.", "items": [{"n": 11, "q": "All prize winners will have their stories printed in the magazine Keep Writing.", "answer": "B"}, {"n": 12, "q": "Most people entering the competition last year followed the advice they were given.", "answer": "A"}, {"n": 13, "q": "Writers should remember to check that any information they use is correct.", "answer": "A"}, {"n": 14, "q": "The magazine is looking for stories which have an unexpected ending.", "answer": "A"}, {"n": 15, "q": "Writers are encouraged to describe the people in their stories clearly.", "answer": "A"}, {"n": 16, "q": "Stories should either be written clearly by hand or typed.", "answer": "B"}, {"n": 17, "q": "Late entries can be faxed if necessary.", "answer": "B"}, {"n": 18, "q": "The magazine will send back all stories which have failed to be selected.", "answer": "B"}, {"n": 19, "q": "The rules of the competition are different this year from last year.", "answer": "A"}, {"n": 20, "q": "Writers can enter stories which magazines outside Britain have already printed.", "answer": "B"}]}, {"part": 4, "title": "", "text": "At 32, I have just finished my first year at university. As well as attending lectures regularly, I have had to learn to read books quickly and write long essays.\n\nI decided to go to university after fourteen years away from the classroom. As a secretary, although I was earning a reasonable amount of money, I was bored doing something where I hardly had to think. I became more and more depressed by the idea that I was stuck in the job. I was jealous of the students at the local university, who looked happy, carefree and full of hope, and part of something that I wanted to explore further.\n\nHowever, now that I've actually become a student I find it hard to mix with younger colleagues. They are always mistaking me for a lecturer and asking me questions I can’t answer. I also feel separated from the lecturers because, although we are the same age, I know so much less than them. But I am glad of this opportunity to study because I know you need a qualification to get a rewarding job, which is really important to me. Unlike most eighteen-year-olds, I much prefer a weekend with my books to one out partying. Then there are the normal student benefits of long holidays and theatre and cinema discounts. I often have doubts about what I'll do after university, but I hope that continuing my education at this late date has been a wise choice.", "items": [{"n": 21, "q": "What is the writer trying to do in the text?", "options": ["help lecturers understand older students", "explain her reasons for returning to study", "suggest some good methods for studying", "complain about the attitude of young students"], "answer": "B"}, {"n": 22, "q": "What can a reader find out about the writer from the text?", "options": ["when she left school", "how long her university course is", "where she will work in future", "what subject she is studying"], "answer": "A"}, {"n": 23, "q": "How did the writer feel about her job as a secretary?", "options": ["Her salary wasn’t good enough.", "It gave her the opportunity to study.", "It didn’t make use of her brain.", "Her colleagues made her depressed."], "answer": "C"}, {"n": 24, "q": "In her spare time, the writer likes to", "options": ["go out to parties.", "earn some money.", "travel a lot.", "do extra study."], "answer": "D"}, {"n": 25, "q": "Which of these sentences describes the writer?", "options": ["She realises the value of a university degree.", "She gets on well with the other students.", "She is confident about the future.", "She finds university life easier than she expected."], "answer": "A"}]}, {"part": 5, "title": "Henry Ford", "text": "Henry Ford was born (0) ……… (on) a farm in Michigan in 1863 but he did not like farming. When he was fifteen he began work as a mechanic and in 1893 he built his first car. After he [26] driven it 1,500 kilometres, he sold it and built two bigger cars. Then, in 1903, he [27] the Ford Motor Company. By [28] strong but light steel, he built cheap cars for [29] people to buy. In 1908, he built the first Ford Model “T”, [30] sold for $825. He was soon selling 100 cars [31] day. By 1927, the Ford Motor Company was [32] $700 million. Early Ford cars were simple and cheap, but [33] things simple sometimes [34] less choice. “You [35] have any colour you like,” said Henry Ford of the Model T, “as long as it’s black.”", "gaps": {"26": {"options": ["is", "was", "had", "has"], "answer": "C"}, "27": {"options": ["raised", "started", "led", "appeared"], "answer": "B"}, "28": {"options": ["putting", "operating", "using", "managing"], "answer": "C"}, "29": {"options": ["usual", "ordinary", "general", "typical"], "answer": "B"}, "30": {"options": ["where", "which", "who", "what"], "answer": "B"}, "31": {"options": ["a", "some", "the", "one"], "answer": "A"}, "32": {"options": ["rich", "worth", "expensive", "dear"], "answer": "B"}, "33": {"options": ["remaining", "staying", "keeping", "holding"], "answer": "C"}, "34": {"options": ["meant", "decided", "planned", "intended"], "answer": "A"}, "35": {"options": ["will", "ought", "need", "can"], "answer": "D"}}}], "writing": [{"part": 1, "title": "Here are some sentences about a school trip to a museum.", "items": [{"n": 1, "first": "The museum was near the school.", "before": "The museum was not", "after": "the school.", "answers": ["far from", "far away from"]}, {"n": 2, "first": "It cost £3 to visit the museum.", "before": "They had to", "after": "£3 to visit the museum.", "answers": ["pay"]}, {"n": 3, "first": "The class was taken around the museum by a guide.", "before": "A museum guide", "after": "around the museum.", "answers": ["took the class", "showed the class"]}, {"n": 4, "first": "They did not leave until 4 o’clock.", "before": "It was 4 o’clock", "after": "they left the museum.", "answers": ["when", "before"]}, {"n": 5, "first": "Everybody thought that the museum visit was boring.", "before": "Everybody was", "after": "by the museum visit.", "answers": ["bored"]}]}, {"part": 2, "items": [{"n": 6, "kind": "message", "task": "Your friend Alex has invited you to go to the cinema tomorrow, but you can’t go.\n\nWrite an email to Alex. In your email, you should\n• apologise\n• explain why you can’t go\n• invite Alex to do something with you another day.\n\nWrite 35–45 words on your answer sheet.", "points": ["scusarsi perché non può andare al cinema", "spiegare perché non può andare", "proporre un altro invito con i dettagli"]}]}, {"part": 3, "items": [{"n": 7, "kind": "letter", "task": "This is part of a letter you receive from an English friend.\n\nWe had dinner at a new restaurant yesterday. It was great! How often do you eat out? What’s your favourite restaurant like?\n\nNow write a letter, answering your friend’s questions.\nWrite your letter in about 100 words on your answer sheet."}, {"n": 8, "kind": "story", "task": "Your English teacher has asked you to write a story.\nYour story must begin with this sentence:\n\nI had a real surprise when I turned on the television.\n\nWrite your story in about 100 words on your answer sheet."}]}], "listening": [{"part": 1, "audio": "audio/pet6-t4-l1.mp3", "items": [{"n": 1, "q": "What did the thieves steal?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 2, "q": "What present will they take?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 3, "q": "What will the woman eat tonight?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "C"}, {"n": 4, "q": "How much will the girl’s ticket cost?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "B"}, {"n": 5, "q": "What is the grandmother’s job now?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 6, "q": "Which button has the boy lost?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}, {"n": 7, "q": "What will the man do first?", "img": "data:image/jpeg;base64,", "options": ["", "", ""], "answer": "A"}]}, {"part": 2, "intro": "You will hear Sarah Brown talking about her work as a television weather forecaster.", "audio": "audio/pet6-t4-l2.mp3", "items": [{"n": 8, "q": "How long has Sarah worked as a weather forecaster?", "options": ["two years", "seven years", "thirty years"], "answer": "B"}, {"n": 9, "q": "What does Sarah say about her job?", "options": ["She sometimes has to work at night.", "She enjoys getting up early.", "She works ten or twelve hours a day."], "answer": "A"}, {"n": 10, "q": "When Sarah does a weather forecast,", "options": ["she prepares it in advance.", "she sometimes forgets her words.", "she worries about making a mistake."], "answer": "A"}, {"n": 11, "q": "Sarah’s husband", "options": ["works on the same days each week.", "wants to move nearer his work.", "spends a lot of time travelling."], "answer": "C"}, {"n": 12, "q": "Sarah is pleased because she", "options": ["has got her pilot’s licence.", "taught her husband to play tennis.", "took part in a long race."], "answer": "C"}, {"n": 13, "q": "A man in India wanted", "options": ["to meet Sarah’s family.", "a photo of Sarah.", "to receive a letter from Sarah."], "answer": "B"}]}, {"part": 3, "intro": "You will hear a radio talk about holidays in Northumberland.", "audio": "audio/pet6-t4-l3.mp3", "notes": "Holidays in Northumberland\n\nUseful Information\n• Read Peter Green’s book called “[14] around Northumberland”.\n• Lots of things to see, for example [15]\n• Accommodation in flats, hotels, cottages or bed and breakfast places.\n• Best time to go is [16]\n\nBike Hire\n• One week – £35\n• Two weeks – £ [17]\n\nLocal Events\n• June – Food Festival\n• August – International Festival of [18]\n\nNational Park Activities\n• Guided walks\n• Photography\n• [19]", "answers": {"14": ["cycling"], "15": ["castle", "castles", "a castle"], "16": ["spring", "in spring", "in the spring", "spring time", "springtime", "in the spring time"], "17": ["55", "£55"], "18": ["music"], "19": ["bird watching", "birds watching", "birdwatching"]}}, {"part": 4, "intro": "You will hear a conversation between a girl called Julia and her father, about choosing a course at university.", "audio": "audio/pet6-t4-l4.mp3", "items": [{"n": 20, "q": "Julia wants to choose a course as soon as possible.", "answer": "B"}, {"n": 21, "q": "Julia’s father thinks that studying business may be boring.", "answer": "B"}, {"n": 22, "q": "Julia’s father believes Julia’s friend is making the wrong choice.", "answer": "A"}, {"n": 23, "q": "Julia’s father thinks she might find studying business too difficult.", "answer": "B"}, {"n": 24, "q": "Julia is confident about her maths.", "answer": "A"}, {"n": 25, "q": "Julia is keen to consider her father’s suggestion.", "answer": "A"}]}]};
